import base64,hashlib,pathlib,subprocess,sys,json,platform,traceback,zipfile,os
from datetime import datetime,timezone
ROOT=pathlib.Path('/content/tep-critical-fourier109');ROOT.mkdir(exist_ok=False)
OUT=ROOT/'evidence';OUT.mkdir()
SOURCE_SHA='4bb460e1537ed2f0bdc8b845b9c0304cfe3128c7'
EXPECTED='11db01f92651edd6497f80ef28b3a4dd69c9a7ab90769f4edc00ff0e33462f45'
DATA=''
report={'run':'109','started_utc':datetime.now(timezone.utc).isoformat(),'status':'RUNNING',
'fixture_source_sha':SOURCE_SHA,'fixture_sha256':EXPECTED,'general_theorem_verified':False,
'new_lean_run':False,'independent_review':False,'terminal_reproduction':False,'steps':[]}
try:
    data=base64.b64decode(DATA)
    if hashlib.sha256(data).hexdigest()!=EXPECTED:raise ValueError('Fixture hash mismatch')
    script=OUT/'exact-fixtures.py';script.write_bytes(data)
    rows=[]
    for name,flags in [('normal',[]),('optimized',['-O'])]:
        p=subprocess.run([sys.executable]+flags+[str(script)],text=True,capture_output=True,timeout=120)
        (OUT/(name+'.stdout.txt')).write_text(p.stdout);(OUT/(name+'.stderr.txt')).write_text(p.stderr)
        report['steps'].append({'mode':name,'exit_code':p.returncode})
        if p.returncode:raise RuntimeError(name+' failed: '+p.stderr[-4000:])
        row=json.loads(p.stdout)
        if row['status']!='EXACT_FINITE_ADAPTER_FIXTURES_ACCEPTED' or row['accepted']!=4 or row['real_mutations_rejected']!=16 or row['optimized']!=(name=='optimized') or row['general_theorem_verified']:
            raise ValueError('Diagnostic result incorrect '+name)
        rows.append(row)
    if rows[0]['fixtures']!=rows[1]['fixtures']:raise ValueError('Mode fixture mismatch')
    report.update(status='EXACT_FINITE_DIAGNOSTICS_PASS',fixtures=rows[0]['fixtures'],accepted_each=4,
                  real_mutations_rejected_each=16,mode_fixture_outputs_match=True)
except BaseException as e:
    report['status']='FAIL';report['error']=repr(e)
    (OUT/'exception.txt').write_text(traceback.format_exc());print(traceback.format_exc(),flush=True)
finally:
    report['finished_utc']=datetime.now(timezone.utc).isoformat()
    report['colab_gpu_env']=os.environ.get('COLAB_GPU','unset')
    (OUT/'report.json').write_text(json.dumps(report,indent=2))
    (OUT/'python-version.txt').write_text(sys.version+'\n'+platform.platform())
    (OUT/'recipe109.py').write_bytes(pathlib.Path(__file__).read_bytes())
    manifest={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(OUT.iterdir()) if p.is_file()}
    (OUT/'manifest.json').write_text(json.dumps(manifest,indent=2))
    bundle=ROOT/'diagnostics109.zip'
    with zipfile.ZipFile(bundle,'w',zipfile.ZIP_DEFLATED) as z:
        for p in sorted(OUT.iterdir()):
            if p.is_file():z.write(p,p.name)
    print('FINAL_REPORT='+json.dumps(report),flush=True)
    print('BUNDLE_SHA256='+hashlib.sha256(bundle.read_bytes()).hexdigest(),flush=True)
    print('EVIDENCE_BASE64_BEGIN='+base64.b64encode(bundle.read_bytes()).decode()+'=EVIDENCE_BASE64_END',flush=True)
    print('FINITE_DIAGNOSTICS_ONLY; releasing own runtime.',flush=True)
    from google.colab import runtime
    runtime.unassign()